sap.ui.require.preload({
  "com/sap/atcanalysis/Component.js": "sap.ui.define([\"sap/ui/core/UIComponent\"], (UIComponent) => {\n  \"use strict\";\n  return UIComponent.extend(\"com.sap.atcanalysis.Component\", {\n    metadata: { manifest: \"json\" },\n    init() {\n      UIComponent.prototype.init.apply(this, arguments);\n      this.getRouter().initialize();\n    },\n  });\n});\n",
  "com/sap/atcanalysis/controller/Results.controller.js": "sap.ui.define([\n  \"sap/ui/core/mvc/Controller\",\n  \"sap/ui/model/json/JSONModel\",\n  \"sap/m/MessageToast\",\n  \"sap/m/MessageBox\",\n  \"sap/m/CustomListItem\",\n  \"sap/m/StandardListItem\",\n  \"sap/m/HBox\",\n  \"sap/m/Button\",\n  \"sap/m/Text\",\n  \"sap/m/ObjectStatus\",\n], (Controller, JSONModel, MessageToast, MessageBox, CustomListItem, StandardListItem, HBox, Button, Text, ObjectStatus) => {\n  \"use strict\";\n\n  return Controller.extend(\"com.sap.atcanalysis.controller.Results\", {\n\n    onInit() {\n      const router = this.getOwnerComponent().getRouter();\n      router.getRoute(\"results\").attachPatternMatched(this._onRouteMatched, this);\n    },\n\n    async _onRouteMatched(oEvent) {\n      this._jobId = oEvent.getParameter(\"arguments\").jobId;\n      // Retrieve the CF instance affinity set during upload so all reads go to the same instance\n      try { this._cfAppInstance = sessionStorage.getItem(\"cfAppInstance\") || null; } catch (_) { this._cfAppInstance = null; }\n      this._resetView();\n      await this._loadResults();\n    },\n\n    _resetView() {\n      [\"summaryPanel\",\"chartsPanel1\",\"chartsPanel2\",\"exceptionsPanel\",\"downloadsPanel\",\"downloadAllBtn\"].forEach(id => {\n        this.byId(id)?.setVisible(false);\n      });\n      this.byId(\"loadingIndicator\")?.setVisible(true);\n      this.byId(\"errorStrip\")?.setVisible(false);\n      this.byId(\"artifactsList\")?.removeAllItems();\n      this.byId(\"unmaintainedNsList\")?.removeAllItems();\n    },\n\n    async _loadResults() {\n      try {\n        const instanceHeaders = this._cfAppInstance\n          ? { \"X-CF-App-Instance\": this._cfAppInstance }\n          : {};\n\n        // Fetch job status — retry up to 5 times (2s apart) in case of brief DB lag after navigation\n        let job;\n        for (let attempt = 0; attempt < 5; attempt++) {\n          const resp = await fetch(\n            `/api/atc/Jobs(id='${this._jobId}')?$select=status,statusMsg,totalCount,hcaCount,s4Count,spddCount,spauCount,fitGapDeltaCount,nsFindings`,\n            { headers: instanceHeaders }\n          );\n          const data = await resp.json();\n          job = data.value?.[0] || data;\n          if (job.status === \"done\" || job.status === \"failed\") break;\n          // Still running — wait 2s and retry\n          await new Promise(r => setTimeout(r, 2000));\n        }\n\n        if (job.status === \"failed\") {\n          this._showError(`Analysis failed: ${job.statusMsg}`);\n          return;\n        }\n        if (job.status !== \"done\") {\n          this._showError(`Job is not complete (status: ${job.status}). Please wait and refresh.`);\n          return;\n        }\n\n        // Fetch chart data via function\n        let atcData = null;\n        try {\n          const cdResp = await fetch(\n            `/api/atc/Jobs(id='${this._jobId}')/ATCService.getChartData()`,\n            { headers: instanceHeaders }\n          );\n          const cdJson = await cdResp.json();\n          const raw = cdJson.value;\n          if (raw && typeof raw === \"string\" && raw !== \"null\") {\n            atcData = JSON.parse(raw);\n          } else if (raw && typeof raw === \"object\") {\n            atcData = raw;\n          }\n        } catch (chartErr) {\n          console.warn(\"Chart data unavailable:\", chartErr.message);\n        }\n\n        // Fetch artifacts\n        const artResp = await fetch(\n          `/api/atc/Artifacts?$filter=jobId eq '${this._jobId}'&$select=id,role,filename,mimeType,size`,\n          { headers: instanceHeaders }\n        );\n        const artData = await artResp.json();\n        const artifacts = artData.value || [];\n\n        if (!artifacts.length) {\n          this._showError(\"No output files found for this job. The server may have restarted and lost the session data. Please run the analysis again.\");\n          return;\n        }\n\n        this.byId(\"loadingIndicator\").setVisible(false);\n        this._renderSummary(job);\n        this._renderCharts(atcData);\n        this._renderArtifacts(artifacts);\n        this._renderExceptions(job);\n\n        this.byId(\"summaryPanel\").setVisible(true);\n        this.byId(\"chartsPanel1\").setVisible(!!atcData);\n        this.byId(\"chartsPanel2\").setVisible(!!atcData);\n        this.byId(\"downloadsPanel\").setVisible(true);\n        this.byId(\"downloadAllBtn\").setVisible(true);\n\n      } catch (err) {\n        this._showError(`Failed to load results: ${err.message}`);\n      }\n    },\n\n    _renderSummary(job) {\n      this.byId(\"totalCountTile\").setValue(String(job.totalCount || 0));\n      this.byId(\"hcaCountTile\").setValue(String(job.hcaCount   || 0));\n      this.byId(\"s4CountTile\").setValue(String(job.s4Count     || 0));\n      this.byId(\"spddTile\").setValue(String(job.spddCount || 0));\n      this.byId(\"spauTile\").setValue(String(job.spauCount || 0));\n    },\n\n    _renderCharts(atcData) {\n      if (!atcData) return;\n\n      // Slide 5 — remediation categories\n      const slide5Model = new JSONModel({\n        items: (atcData.slide5Categories || []).map((cat, i) => ({\n          category: cat,\n          count:    (atcData.slide5Values || [])[i] || 0,\n        })),\n      });\n      this.byId(\"slide5Dataset\").setModel(slide5Model);\n      this.byId(\"slide5Dataset\").bindAggregation(\"data\", { path: \"/items\" });\n      _applyVizProps(this.byId(\"slide5Chart\"), \"Remediation Categories\");\n\n      // Slide 4 — object types\n      const slide4Model = new JSONModel({\n        items: (atcData.uniqueObjTypes || []).map((type, i) => ({\n          type,\n          count: (atcData.uniqueObjCounts || [])[i] || 0,\n        })),\n      });\n      this.byId(\"slide4Dataset\").setModel(slide4Model);\n      this.byId(\"slide4Dataset\").bindAggregation(\"data\", { path: \"/items\" });\n      _applyVizProps(this.byId(\"slide4Chart\"), \"Object Types\");\n\n      // HCA waterfall\n      const hcaValues = atcData.chart7Values || [];\n      const hcaTotal  = hcaValues.reduce((s, v) => s + (v || 0), 0);\n      const hcaModel = new JSONModel({\n        items: (atcData.chart7Categories || []).map((cat, i) => ({\n          category: cat,\n          count:    hcaValues[i] || 0,\n        })),\n      });\n      this.byId(\"hcaDataset\").setModel(hcaModel);\n      this.byId(\"hcaDataset\").bindAggregation(\"data\", { path: \"/items\" });\n      this.byId(\"hcaChartLabel\").setText(`HCA Impact Breakdown — ${hcaTotal} findings across all categories`);\n      _applyVizProps(this.byId(\"hcaChart\"), \"HCA Breakdown\");\n\n      // S/4H waterfall\n      const s4hValues = atcData.chart8Values || [];\n      const s4hTotal  = s4hValues.reduce((s, v) => s + (v || 0), 0);\n      const s4hModel = new JSONModel({\n        items: (atcData.chart8Categories || []).map((cat, i) => ({\n          category: cat,\n          count:    s4hValues[i] || 0,\n        })),\n      });\n      this.byId(\"s4hDataset\").setModel(s4hModel);\n      this.byId(\"s4hDataset\").bindAggregation(\"data\", { path: \"/items\" });\n      this.byId(\"s4hChartLabel\").setText(`S/4HANA Impact Breakdown — ${s4hTotal} findings across all categories`);\n      _applyVizProps(this.byId(\"s4hChart\"), \"S/4HANA Breakdown\");\n    },\n\n    _renderArtifacts(artifacts) {\n      const list = this.byId(\"artifactsList\");\n      list.removeAllItems();\n\n      const filtered = artifacts;\n\n      if (!filtered.length) {\n        list.addItem(new CustomListItem({\n          content: [new Text({ text: \"No output files generated yet.\" })]\n        }));\n        return;\n      }\n\n      const roleLabels = {\n        atc_result: \"ATC Classified Results (XLSX)\",\n        tua:        \"TUA Analysis (XLSX)\",\n        pptx:       \"Presentation (PPTX)\",\n        estimation: \"Effort Estimation (XLSX)\",\n      };\n\n      filtered.forEach(art => {\n        // Per-chunk API artifacts have roles like atc_result_chunk_1, atc_result_chunk_2, ...\n        let label;\n        const chunkMatch = art.role && art.role.match(/^atc_result_chunk_(\\d+)$/);\n        if (chunkMatch) {\n          label = `API Result — Chunk ${chunkMatch[1]} (XLS)`;\n        } else {\n          label = roleLabels[art.role] || art.filename;\n        }\n        const sizeText = _formatSize(art.size);\n        const item = new CustomListItem({\n          content: [\n            new HBox({\n              alignItems: \"Center\",\n              justifyContent: \"SpaceBetween\",\n              items: [\n                new HBox({\n                  alignItems: \"Center\",\n                  items: [\n                    new ObjectStatus({\n                      icon:  _roleIcon(art.role),\n                      state: \"Success\",\n                      class: \"sapUiSmallMarginEnd\",\n                    }),\n                    new Text({ text: `${label} — ${art.filename} (${sizeText})` }),\n                  ],\n                }),\n                new Button({\n                  text:  \"Download\",\n                  icon:  \"sap-icon://download\",\n                  type:  \"Transparent\",\n                  press: () => { _downloadArtifact(art.id, art.filename, this._cfAppInstance); },\n                }),\n              ],\n            }),\n          ],\n        });\n        list.addItem(item);\n      });\n    },\n\n    _renderExceptions(job) {\n      const fitGapDelta = job.fitGapDeltaCount || 0;\n      let unmaintained = [];\n      if (job.nsFindings) {\n        try {\n          const f = JSON.parse(job.nsFindings);\n          unmaintained = f.unmaintained || [];\n        } catch (_) {}\n      }\n\n      // Always show exceptions panel — it has Fit Gap Delta even for ATC-only jobs\n      this.byId(\"exceptionFitGapDelta\").setText(String(fitGapDelta));\n\n      const unmaintainedList = this.byId(\"unmaintainedNsList\");\n      unmaintained.forEach(ns => {\n        unmaintainedList.addItem(new StandardListItem({ title: ns, icon: \"sap-icon://warning\" }));\n      });\n\n      this.byId(\"exceptionsPanel\").setVisible(true);\n    },\n\n    async onDownloadAll() {\n      if (!this._jobId) return;\n      try {\n        const headers = this._cfAppInstance ? { \"X-CF-App-Instance\": this._cfAppInstance } : {};\n        const resp = await fetch(`/atc/downloadAll/${this._jobId}`, { headers });\n        if (!resp.ok) {\n          const errText = await resp.text();\n          this._showError(`Download failed: ${errText.slice(0, 200)}`);\n          return;\n        }\n        const blob = await resp.blob();\n        const url  = URL.createObjectURL(blob);\n        const disp = resp.headers.get(\"Content-Disposition\") || \"\";\n        const nameMatch = disp.match(/filename=\"?([^\"]+)\"?/);\n        const filename  = nameMatch ? nameMatch[1] : \"ATC_Results.zip\";\n        const link = document.createElement(\"a\");\n        link.href     = url;\n        link.download = filename;\n        link.click();\n        URL.revokeObjectURL(url);\n      } catch (err) {\n        this._showError(`Download error: ${err.message}`);\n      }\n    },\n\n    onNavBack() {\n      MessageBox.confirm(\n        \"Going back will clear all uploaded files and start a new analysis. Continue?\",\n        {\n          title: \"Leave Results Page\",\n          actions: [MessageBox.Action.YES, MessageBox.Action.NO],\n          emphasizedAction: MessageBox.Action.NO,\n          onClose: (action) => {\n            if (action !== MessageBox.Action.YES) return;\n            this.getOwnerComponent().getRouter().navTo(\"home\");\n          },\n        }\n      );\n    },\n\n    _showError(msg) {\n      this.byId(\"loadingIndicator\").setVisible(false);\n      const strip = this.byId(\"errorStrip\");\n      strip.setText(msg).setVisible(true);\n    },\n  });\n});\n\n// ── Helpers ──────────────────────────────────────────────────────────────────\nfunction _applyVizProps(vizFrame, title) {\n  if (!vizFrame) return;\n  vizFrame.setVizProperties({\n    title:  { visible: false },\n    legend: { visible: false },\n    categoryAxis: { title: { visible: false } },\n    valueAxis:    { title: { visible: false } },\n    plotArea:     { dataLabel: { visible: true } },\n  });\n}\n\nasync function _downloadArtifact(artifactId, filename, cfAppInstance) {\n  try {\n    const headers = cfAppInstance ? { \"X-CF-App-Instance\": cfAppInstance } : {};\n    const resp = await fetch(`/atc/download/${artifactId}`, { headers });\n    if (!resp.ok) { console.error(\"Download failed\", resp.status); return; }\n    const blob = await resp.blob();\n    const url  = URL.createObjectURL(blob);\n    const link = document.createElement(\"a\");\n    link.href     = url;\n    link.download = filename;\n    link.click();\n    URL.revokeObjectURL(url);\n  } catch (err) {\n    console.error(\"Download error:\", err.message);\n  }\n}\n\nfunction _roleIcon(role) {\n  if (role && role.startsWith(\"atc_result_chunk_\")) return \"sap-icon://document\";\n  const icons = {\n    atc_result: \"sap-icon://document\",\n    tua:        \"sap-icon://table-chart\",\n    pptx:       \"sap-icon://present\",\n    estimation: \"sap-icon://budget\",\n  };\n  return icons[role] || \"sap-icon://document\";\n}\n\nfunction _formatSize(bytes) {\n  if (!bytes) return \"0 B\";\n  const kb = bytes / 1024;\n  return kb < 1024 ? `${kb.toFixed(1)} KB` : `${(kb/1024).toFixed(1)} MB`;\n}\n",
  "com/sap/atcanalysis/controller/Upload.controller.js": "sap.ui.define([\n  \"sap/ui/core/mvc/Controller\",\n  \"sap/m/MessageToast\",\n  \"sap/m/MessageBox\",\n], (Controller, MessageToast, MessageBox) => {\n  \"use strict\";\n\n  return Controller.extend(\"com.sap.atcanalysis.controller.Upload\", {\n\n    onInit() {\n      this._fileIds = {\n        atc:       null,\n        clone:     null,\n        smodilog:  null,\n        trnspacet: null,\n      };\n      // Store actual File objects from change events\n      this._files = {\n        atc:       null,\n        clone:     null,\n        smodilog:  null,\n        trnspacet: null,\n      };\n      // CF instance affinity: captured from first upload response.\n      // Sent as X-CF-App-Instance on all subsequent requests to guarantee\n      // all data (files, job, runAnalysis) lands on the same CF instance/SQLite DB.\n      this._cfAppInstance = null;\n      // Default analysis mode\n      this._analysisMode = \"atc\";\n      // Default: use App Logic (lower memory, no Cloud Connector needed)\n      this._useAppLogic = true;\n      // Default migration type: Conversion (ECC → S/4HANA)\n      this._migType = \"conversion\";\n      this.getOwnerComponent().getRouter()\n        .getRoute(\"home\")\n        .attachPatternMatched(this._onRouteMatched, this);\n    },\n\n    _onRouteMatched() {\n      this.resetView();\n    },\n\n    resetView() {\n      // Clear file references\n      this._fileIds = { atc: null, clone: null, smodilog: null, trnspacet: null };\n      this._files   = { atc: null, clone: null, smodilog: null, trnspacet: null };\n      this._cfAppInstance = null;\n      this._analysisMode = \"atc\";\n      this._useAppLogic = true;\n      this._migType = \"conversion\";\n      this.byId(\"customerInput\")?.setValue(\"\");\n      this.byId(\"atcFileUploader\")?.clear?.();\n      this.byId(\"cloneFileUploader\")?.clear?.();\n      this.byId(\"smodilogUploader\")?.clear?.();\n      this.byId(\"trnspacetUploader\")?.clear?.();\n      this.byId(\"atcFileStatus\")?.setText(\"No file selected\").setState(\"None\");\n      this.byId(\"cloneFileStatus\")?.setText(\"No file selected\").setState(\"None\");\n      this.byId(\"smodilogStatus\")?.setText(\"No file selected\").setState(\"None\");\n      this.byId(\"trnspacetStatus\")?.setText(\"No file selected\").setState(\"None\");\n      this.byId(\"analysisModeBtn\")?.setSelectedKey(\"atc\");\n\n      this.byId(\"migrationTypeBtn\")?.setSelectedItem(this.byId(\"migConversionItem\"));\n      this.byId(\"errorStrip\")?.setVisible(false);\n      this._applyModeVisibility();\n      this._setRunning(false);\n      this._updateRunButton();\n    },\n\n    // ── Analysis mode change ──────────────────────────────────────────────────\n    onModeChange(oEvent) {\n      this._analysisMode = oEvent.getParameter(\"item\").getKey();\n      this._applyModeVisibility();\n      this._updateRunButton();\n    },\n\n    _applyModeVisibility() {\n      const m = this._analysisMode;\n      const showAtc   = m !== \"tua_only\";\n      const showClone = m === \"atc_clone\" || m === \"atc_tua_clone\";\n      const showTua   = m === \"atc_tua\" || m === \"atc_tua_clone\" || m === \"tua_only\";\n      this.byId(\"atcUploaderPanel\")?.setVisible(showAtc);\n      this.byId(\"cloneUploaderPanel\")?.setVisible(showClone);\n      this.byId(\"tuaUploaderPanel\")?.setVisible(showTua);\n    },\n\n    // ── Customer name change ──────────────────────────────────────────────────\n    onCustomerChange() {\n      this._updateRunButton();\n    },\n\n    // ── Migration type toggle ──────────────────────────────────────────────────\n    onMigrationTypeChange(oEvent) {\n      this._migType = oEvent.getParameter(\"item\").getKey(); // \"conversion\" | \"upgrade\"\n    },\n\n    // ── File selection callbacks ───────────────────────────────────────────────\n    onAtcFileChange(oEvent) {\n      const file = oEvent.getParameter(\"files\")[0];\n      const status = this.byId(\"atcFileStatus\");\n      if (file) {\n        this._files.atc = file;\n        status.setText(file.name).setState(\"Success\");\n      } else {\n        this._files.atc = null;\n        this._fileIds.atc = null;\n        status.setText(\"No file selected\").setState(\"None\");\n      }\n      this._updateRunButton();\n    },\n\n    onOptionalFileChange(oEvent) {\n      const file = oEvent.getParameter(\"files\")[0];\n      const uid  = oEvent.getSource().getId();\n      const role = uid.includes(\"clone\")     ? \"clone\"\n                 : uid.includes(\"smodilog\")  ? \"smodilog\"\n                 : uid.includes(\"trnspacet\") ? \"trnspacet\"\n                 : null;\n      if (role) {\n        this._files[role] = file || null;\n        const statusMap = {\n          clone:     \"cloneFileStatus\",\n          smodilog:  \"smodilogStatus\",\n          trnspacet: \"trnspacetStatus\",\n        };\n        const statusId = statusMap[role];\n        if (statusId) {\n          this.byId(statusId)\n            ?.setText(file ? file.name : \"No file selected\")\n            .setState(file ? \"Success\" : \"None\");\n        }\n        this._updateRunButton();\n      }\n    },\n\n    // ── Run Analysis ──────────────────────────────────────────────────────────\n    async onRunAnalysis() {\n      const customer = this.byId(\"customerInput\").getValue().trim();\n      const m = this._analysisMode;\n\n      if (!customer) {\n        MessageBox.error(\"Please enter a customer name.\");\n        return;\n      }\n      if (m !== \"tua_only\" && !this._files.atc) {\n        MessageBox.error(\"Please select the ATC file before running analysis.\");\n        return;\n      }\n\n      this._setRunning(true, \"Uploading files...\");\n      this.byId(\"errorStrip\").setVisible(false);\n\n      try {\n        // Upload all selected files\n        await this._uploadAllFiles();\n\n        if (m !== \"tua_only\" && !this._fileIds.atc) {\n          throw new Error(\"ATC file upload did not return a file ID.\");\n        }\n\n        // Create job — must go to the same instance that received the file uploads\n        this._setRunning(true, \"Creating analysis job...\");\n        const instanceHeaders = this._cfAppInstance\n          ? { \"Content-Type\": \"application/json\", \"X-CF-App-Instance\": this._cfAppInstance }\n          : { \"Content-Type\": \"application/json\" };\n        const createResp = await fetch(\"/atc/jobs/create\", {\n          method:  \"POST\",\n          headers: instanceHeaders,\n          body:    JSON.stringify({\n            customer,\n            analysisMode: this._analysisMode,\n            atcFileId:    this._fileIds.atc      || null,\n            cloneFileId:  this._fileIds.clone    || null,\n            smodilogId:   this._fileIds.smodilog || null,\n            trnspacetId:  this._fileIds.trnspacet|| null,\n            nsOwnerId:    null,\n            useAppLogic:  this._useAppLogic,\n            migType:      this._migType,\n          }),\n        });\n        const createResult = await createResp.json();\n        if (createResult.error) throw new Error(createResult.error);\n\n        const jobId = createResult.jobId;\n        this._setRunning(true, \"Running analysis...\");\n\n        // Trigger analysis — must reach the same instance where job and files live\n        const runHeaders = { \"Content-Type\": \"application/json\" };\n        if (this._cfAppInstance) runHeaders[\"X-CF-App-Instance\"] = this._cfAppInstance;\n        const runResp = await fetch(\n          `/api/atc/Jobs(id='${jobId}')/ATCService.runAnalysis`,\n          {\n            method:  \"POST\",\n            headers: runHeaders,\n            body:    JSON.stringify({}),\n          },\n        );\n        if (!runResp.ok) {\n          const errText = await runResp.text();\n          throw new Error(`Run action failed: ${errText.slice(0, 300)}`);\n        }\n\n        // Poll for completion\n        this._pollJob(jobId);\n\n      } catch (err) {\n        this._setRunning(false);\n        this._showError(err.message);\n      }\n    },\n\n    async _uploadAllFiles() {\n      const roles = [\"atc\", \"clone\", \"smodilog\", \"trnspacet\"];\n      for (const role of roles) {\n        const file = this._files[role];\n        if (!file) continue;\n\n        const fd = new FormData();\n        fd.append(\"file\", file);\n        fd.append(\"role\", role);\n\n        // After the first upload, pin all subsequent requests to the same CF instance.\n        // X-CF-App-Instance: \"<app-guid>:<index>\" forces the gorouter to route to that instance.\n        const headers = {};\n        if (this._cfAppInstance) {\n          headers[\"X-CF-App-Instance\"] = this._cfAppInstance;\n        }\n\n        const resp = await fetch(\"/atc/upload\", { method: \"POST\", headers, body: fd });\n        const result = await resp.json();\n        if (result.error) throw new Error(`Upload failed (${role}): ${result.error}`);\n\n        // Capture instance from first upload so all subsequent requests go there\n        if (!this._cfAppInstance && result.cfAppInstance) {\n          this._cfAppInstance = result.cfAppInstance;\n          // Persist so Results page (different controller) uses the same instance\n          try { sessionStorage.setItem(\"cfAppInstance\", result.cfAppInstance); } catch (_) {}\n          // Plant __VCAP_ID__ affinity cookie by hitting /atc/pin with X-CF-App-Instance.\n          // The gorouter rewrites it to its own affinity value for this instance so the\n          // browser sends it on ALL future requests — including <a> download link clicks\n          // that cannot carry custom headers.\n          try {\n            await fetch(\"/atc/pin\", {\n              method: \"POST\",\n              headers: { \"X-CF-App-Instance\": result.cfAppInstance },\n            });\n          } catch (_) {}\n        }\n\n        this._fileIds[role] = result.fileId;\n\n        // Update status label\n        const statusMap = {\n          atc:       \"atcFileStatus\",\n          clone:     \"cloneFileStatus\",\n          smodilog:  \"smodilogStatus\",\n          trnspacet: \"trnspacetStatus\",\n        };\n        this.byId(statusMap[role])\n          ?.setText(`${result.filename} (${_formatSize(result.size)})`)\n          .setState(\"Success\");\n      }\n    },\n\n    async _pollJob(jobId) {\n      let consecutiveErrors = 0;\n      const poll = async () => {\n        try {\n          const pollHeaders = {};\n          if (this._cfAppInstance) pollHeaders[\"X-CF-App-Instance\"] = this._cfAppInstance;\n          const resp = await fetch(\n            `/api/atc/Jobs(id='${jobId}')?$select=status,statusMsg`,\n            { headers: pollHeaders }\n          );\n\n          // Non-2xx (e.g. 502 from CF during restart) — retry up to 5 times before giving up\n          if (!resp.ok) {\n            consecutiveErrors++;\n            if (consecutiveErrors >= 5) {\n              this._setRunning(false);\n              this._showError(`Analysis server unavailable (HTTP ${resp.status}). Please try again.`);\n              return;\n            }\n            setTimeout(poll, 5000);\n            return;\n          }\n          consecutiveErrors = 0;\n\n          const data   = await resp.json();\n          const status = (data.value?.[0] || data).status;\n          const msg    = (data.value?.[0] || data).statusMsg || \"\";\n\n          this.byId(\"statusText\").setText(msg);\n\n          if (status === \"done\") {\n            this._setRunning(false);\n            MessageToast.show(\"Analysis complete!\", { duration: 2000 });\n            this.getOwnerComponent().getRouter().navTo(\"results\", { jobId });\n            return;\n          }\n          if (status === \"failed\") {\n            this._setRunning(false);\n            this._showError(`Analysis failed: ${msg}`);\n            return;\n          }\n          setTimeout(poll, 4000);\n        } catch (err) {\n          // Network error or JSON parse failure — retry a few times before surfacing\n          consecutiveErrors++;\n          if (consecutiveErrors >= 5) {\n            this._setRunning(false);\n            this._showError(`Polling error: ${err.message}`);\n            return;\n          }\n          setTimeout(poll, 5000);\n        }\n      };\n      setTimeout(poll, 2000);\n    },\n\n    _setRunning(running, msg) {\n      const statusBox = this.byId(\"statusBox\");\n      const runBtn    = this.byId(\"runBtn\");\n      statusBox.setVisible(running);\n      if (!running) runBtn.setEnabled(this._isFormValid());\n      else runBtn.setEnabled(false);\n      if (msg) this.byId(\"statusText\").setText(msg);\n    },\n\n    _isFormValid() {\n      const customer = this.byId(\"customerInput\")?.getValue().trim() || \"\";\n      const m        = this._analysisMode;\n      const hasAtc   = !!this._files.atc;\n      const hasClone = !!this._files.clone;\n      const hasSmod  = !!this._files.smodilog;\n      const hasTrns  = !!this._files.trnspacet;\n\n      if (!customer) return false;\n      switch (m) {\n        case \"tua_only\":      return hasSmod && hasTrns;\n        case \"atc_clone\":     return hasAtc && hasClone;\n        case \"atc_tua\":       return hasAtc && hasSmod && hasTrns;\n        case \"atc_tua_clone\": return hasAtc && hasClone && hasSmod && hasTrns;\n        default:              return hasAtc; // \"atc\"\n      }\n    },\n\n    _updateRunButton() {\n      this.byId(\"runBtn\")?.setEnabled(this._isFormValid());\n    },\n\n    _showError(msg) {\n      const strip = this.byId(\"errorStrip\");\n      strip.setText(msg).setVisible(true);\n    },\n\n    onCloseError() {\n      this.byId(\"errorStrip\").setVisible(false);\n    },\n  });\n});\n\nfunction _formatSize(bytes) {\n  if (!bytes) return \"0 B\";\n  const kb = bytes / 1024;\n  return kb < 1024 ? `${kb.toFixed(1)} KB` : `${(kb/1024).toFixed(1)} MB`;\n}\n",
  "com/sap/atcanalysis/i18n/i18n.properties": "# ATC Analysis i18n\nappTitle=SAP ATC Analysis\nappDescription=SAP ATC Code Conversion Assessment Tool\n\n# Upload page\nuploadTitle=Upload Input Files\ncustomerLabel=Customer Name\ncustomerPlaceholder=Enter customer name\natcFileLabel=ATC Analysis File\nrunButton=Run ATC Analysis\ntuaToggleText=Run TUA Analysis\n\n# Results page\nresultsTitle=Analysis Results\ndownloadAll=Download All (ZIP)\ndownloadFile=Download\nnoArtifacts=No output files generated yet.\n\n# Status messages\nstatusUploading=Uploading files...\nstatusRunning=Running ATC analysis...\nstatusGenerating=Generating output files...\nstatusDone=Analysis complete\nstatusFailed=Analysis failed\n",
  "com/sap/atcanalysis/manifest.json": "{\n  \"_version\": \"1.65.0\",\n  \"sap.app\": {\n    \"id\":          \"com.sap.atcanalysis\",\n    \"type\":        \"application\",\n    \"title\":       \"SAP ATC Analysis\",\n    \"description\": \"SAP ATC Code Analysis Tool\",\n    \"applicationVersion\": { \"version\": \"1.1.0\" },\n    \"dataSources\": {\n      \"ATCService\": {\n        \"uri\":        \"/api/atc/\",\n        \"type\":       \"OData\",\n        \"settings\":   { \"odataVersion\": \"4.0\" }\n      }\n    }\n  },\n  \"sap.ui\": {\n    \"technology\":      \"UI5\",\n    \"icons\":           { \"icon\": \"sap-icon://home-share\" },\n    \"deviceTypes\":     { \"desktop\": true, \"tablet\": true, \"phone\": false },\n    \"supportedThemes\": [\"sap_horizon\", \"sap_fiori_3\"]\n  },\n  \"sap.ui5\": {\n    \"rootView\": {\n      \"viewName\": \"com.sap.atcanalysis.view.App\",\n      \"type\":     \"XML\",\n      \"id\":       \"app\"\n    },\n    \"dependencies\": {\n      \"minUI5Version\": \"1.120.0\",\n      \"libs\": {\n        \"sap.ui.core\":    {},\n        \"sap.m\":          {},\n        \"sap.ui.layout\":  {},\n        \"sap.ui.unified\": {},\n        \"sap.viz\":        {}\n      }\n    },\n    \"contentDensities\": {\n      \"compact\":  true,\n      \"cozy\":     true\n    },\n    \"resources\": {\n      \"css\": [\n        { \"uri\": \"css/style.css\" }\n      ]\n    },\n    \"models\": {\n      \"i18n\": {\n        \"type\":     \"sap.ui.model.resource.ResourceModel\",\n        \"settings\": { \"bundleName\": \"com.sap.atcanalysis.i18n.i18n\" }\n      },\n      \"\": {\n        \"type\": \"sap.ui.model.odata.v4.ODataModel\",\n        \"settings\": {\n          \"serviceUrl\":         \"/api/atc/\",\n          \"synchronizationMode\": \"None\",\n          \"operationMode\":      \"Server\"\n        }\n      }\n    },\n    \"routing\": {\n      \"config\": {\n        \"routerClass\": \"sap.m.routing.Router\",\n        \"viewType\":    \"XML\",\n        \"viewPath\":    \"com.sap.atcanalysis.view\",\n        \"controlId\":   \"appNav\",\n        \"controlAggregation\": \"pages\"\n      },\n      \"routes\": [\n        { \"pattern\": \"\",     \"name\": \"home\",    \"target\": \"upload\" },\n        { \"pattern\": \"results/{jobId}\", \"name\": \"results\", \"target\": \"results\" }\n      ],\n      \"targets\": {\n        \"upload\":  { \"viewName\": \"Upload\" },\n        \"results\": { \"viewName\": \"Results\" }\n      }\n    }\n  }\n}\n",
  "com/sap/atcanalysis/view/App.view.xml": "<mvc:View\n  xmlns:mvc=\"sap.ui.core.mvc\"\n  xmlns=\"sap.m\"\n  xmlns:l=\"sap.ui.layout\"\n  displayBlock=\"true\"\n>\n  <App id=\"appNav\" />\n</mvc:View>\n",
  "com/sap/atcanalysis/view/Results.view.xml": "<mvc:View\n  controllerName=\"com.sap.atcanalysis.controller.Results\"\n  xmlns:mvc=\"sap.ui.core.mvc\"\n  xmlns=\"sap.m\"\n  xmlns:l=\"sap.ui.layout\"\n  xmlns:core=\"sap.ui.core\"\n  xmlns:viz=\"sap.viz.ui5.controls\"\n  xmlns:feeds=\"sap.viz.ui5.controls.common.feeds\"\n  xmlns:vizData=\"sap.viz.ui5.data\"\n  displayBlock=\"true\"\n>\n  <Page\n    id=\"resultsPage\"\n    showHeader=\"false\"\n    backgroundDesign=\"Solid\"\n  >\n    <content>\n      <!-- ── Top Header Bar ──────────────────────────────────────────── -->\n      <HBox\n        justifyContent=\"SpaceBetween\"\n        alignItems=\"Center\"\n        class=\"atcHeaderBar\"\n      >\n        <HBox alignItems=\"Center\">\n          <Button\n            icon=\"sap-icon://nav-back\"\n            press=\".onNavBack\"\n            type=\"Transparent\"\n          />\n          <Image src=\"./img/sap_logo.svg\" height=\"28px\" alt=\"SAP Logo\" class=\"sapUiTinyMarginEnd\" />\n          <Title text=\"Conversion Assessment Tool\" level=\"H4\" titleStyle=\"H4\" />\n        </HBox>\n        <HBox alignItems=\"Center\">\n          <Button\n            id=\"downloadAllBtn\"\n            text=\"Download All (ZIP)\"\n            icon=\"sap-icon://download\"\n            type=\"Emphasized\"\n            press=\".onDownloadAll\"\n            visible=\"false\"\n          />\n        </HBox>\n      </HBox>\n\n      <l:VerticalLayout width=\"100%\" class=\"sapUiSmallMarginTop sapUiSmallMarginBeginEnd\">\n\n        <!-- ── Loading / Error state ─────────────────────────────────── -->\n        <BusyIndicator id=\"loadingIndicator\" size=\"2rem\" class=\"sapUiMediumMarginTop\" />\n        <MessageStrip\n          id=\"errorStrip\"\n          type=\"Error\"\n          showIcon=\"true\"\n          visible=\"false\"\n          class=\"sapUiSmallMarginBottom\"\n        />\n\n        <!-- ── Summary KPI Panel ──────────────────────────────────────── -->\n        <Panel\n          id=\"summaryPanel\"\n          visible=\"false\"\n          headerText=\"Analysis Summary\"\n          expandable=\"true\"\n          expanded=\"true\"\n          class=\"sapUiSmallMarginBottom\"\n        >\n          <content>\n            <l:Grid defaultSpan=\"XL2 L3 M6 S12\" class=\"sapUiSmallMarginTop sapUiSmallMarginBottom\">\n              <l:content>\n                <GenericTile\n                  header=\"Total ATC Impacts\"\n                  subheader=\"All findings\"\n                  class=\"sapUiTinyMarginEnd\"\n                >\n                  <tileContent>\n                    <TileContent>\n                      <content>\n                        <NumericContent\n                          id=\"totalCountTile\"\n                          value=\"0\"\n                          scale=\"\"\n                          valueColor=\"None\"\n                          indicator=\"None\"\n                          truncateValueTo=\"6\"\n                        />\n                      </content>\n                    </TileContent>\n                  </tileContent>\n                </GenericTile>\n              </l:content>\n              <l:content>\n                <GenericTile\n                  header=\"HCA Impacts\"\n                  subheader=\"HANA Code Adaptation\"\n                  class=\"sapUiTinyMarginEnd\"\n                >\n                  <tileContent>\n                    <TileContent>\n                      <content>\n                        <NumericContent\n                          id=\"hcaCountTile\"\n                          value=\"0\"\n                          valueColor=\"Critical\"\n                          truncateValueTo=\"6\"\n                        />\n                      </content>\n                    </TileContent>\n                  </tileContent>\n                </GenericTile>\n              </l:content>\n              <l:content>\n                <GenericTile\n                  header=\"S/4HANA Impacts\"\n                  subheader=\"S/4HANA Impact\"\n                  class=\"sapUiTinyMarginEnd\"\n                >\n                  <tileContent>\n                    <TileContent>\n                      <content>\n                        <NumericContent\n                          id=\"s4CountTile\"\n                          value=\"0\"\n                          valueColor=\"Critical\"\n                          truncateValueTo=\"6\"\n                        />\n                      </content>\n                    </TileContent>\n                  </tileContent>\n                </GenericTile>\n              </l:content>\n              <l:content>\n                <GenericTile\n                  header=\"SPDD\"\n                  subheader=\"Dictionary Adjustments\"\n                  class=\"sapUiTinyMarginEnd\"\n                >\n                  <tileContent>\n                    <TileContent>\n                      <content>\n                        <NumericContent\n                          id=\"spddTile\"\n                          value=\"0\"\n                          scale=\"\"\n                          valueColor=\"None\"\n                          indicator=\"None\"\n                          truncateValueTo=\"6\"\n                        />\n                      </content>\n                    </TileContent>\n                  </tileContent>\n                </GenericTile>\n              </l:content>\n              <l:content>\n                <GenericTile\n                  header=\"SPAU\"\n                  subheader=\"Object Adjustments\"\n                  class=\"sapUiTinyMarginEnd\"\n                >\n                  <tileContent>\n                    <TileContent>\n                      <content>\n                        <NumericContent\n                          id=\"spauTile\"\n                          value=\"0\"\n                          scale=\"\"\n                          valueColor=\"None\"\n                          indicator=\"None\"\n                          truncateValueTo=\"6\"\n                        />\n                      </content>\n                    </TileContent>\n                  </tileContent>\n                </GenericTile>\n              </l:content>\n            </l:Grid>\n          </content>\n        </Panel>\n\n        <!-- ── Charts Row 1: Slide 4 (Object Types) + Slide 5 (Remediation) ── -->\n        <Panel\n          id=\"chartsPanel1\"\n          visible=\"false\"\n          headerText=\"Object Classification\"\n          expandable=\"true\"\n          expanded=\"false\"\n          class=\"sapUiSmallMarginBottom\"\n        >\n          <content>\n            <l:Grid defaultSpan=\"XL6 L6 M12 S12\">\n              <l:content>\n                <Label text=\"Unique Impacted Object Types\" design=\"Bold\" textAlign=\"Center\" width=\"100%\" class=\"sapUiTinyMarginBottom\" />\n                <viz:VizFrame\n                  id=\"slide4Chart\"\n                  uiConfig=\"{applicationSet: 'fiori'}\"\n                  vizType=\"bar\"\n                  height=\"400px\"\n                  width=\"100%\"\n                >\n                  <viz:dataset>\n                    <vizData:FlattenedDataset id=\"slide4Dataset\">\n                      <vizData:dimensions>\n                        <vizData:DimensionDefinition name=\"Type\" value=\"{type}\" />\n                      </vizData:dimensions>\n                      <vizData:measures>\n                        <vizData:MeasureDefinition name=\"Objects\" value=\"{count}\" />\n                      </vizData:measures>\n                    </vizData:FlattenedDataset>\n                  </viz:dataset>\n                  <viz:feeds>\n                    <feeds:FeedItem uid=\"categoryAxis\" type=\"Dimension\" values=\"Type\"    />\n                    <feeds:FeedItem uid=\"valueAxis\"    type=\"Measure\"   values=\"Objects\" />\n                  </viz:feeds>\n                </viz:VizFrame>\n              </l:content>\n              <l:content>\n                <Label text=\"Remediation Categories (Unique Objects)\" design=\"Bold\" textAlign=\"Center\" width=\"100%\" class=\"sapUiTinyMarginBottom\" />\n                <viz:VizFrame\n                  id=\"slide5Chart\"\n                  uiConfig=\"{applicationSet: 'fiori'}\"\n                  vizType=\"bar\"\n                  height=\"400px\"\n                  width=\"100%\"\n                >\n                  <viz:dataset>\n                    <vizData:FlattenedDataset id=\"slide5Dataset\">\n                      <vizData:dimensions>\n                        <vizData:DimensionDefinition name=\"Category\" value=\"{category}\" />\n                      </vizData:dimensions>\n                      <vizData:measures>\n                        <vizData:MeasureDefinition name=\"Count\" value=\"{count}\" />\n                      </vizData:measures>\n                    </vizData:FlattenedDataset>\n                  </viz:dataset>\n                  <viz:feeds>\n                    <feeds:FeedItem uid=\"categoryAxis\" type=\"Dimension\" values=\"Category\" />\n                    <feeds:FeedItem uid=\"valueAxis\"    type=\"Measure\"   values=\"Count\"    />\n                  </viz:feeds>\n                </viz:VizFrame>\n              </l:content>\n            </l:Grid>\n          </content>\n        </Panel>\n\n        <!-- ── Charts Row 2: HCA + S/4H waterfall ────────────────────── -->\n        <Panel\n          id=\"chartsPanel2\"\n          visible=\"false\"\n          headerText=\"Impact Breakdown\"\n          expandable=\"true\"\n          expanded=\"false\"\n          class=\"sapUiSmallMarginBottom\"\n        >\n          <content>\n            <l:Grid defaultSpan=\"XL6 L6 M12 S12\">\n              <l:content>\n                <Label id=\"hcaChartLabel\" text=\"\" design=\"Bold\" textAlign=\"Center\" width=\"100%\" class=\"sapUiTinyMarginBottom\" />\n                <viz:VizFrame\n                  id=\"hcaChart\"\n                  uiConfig=\"{applicationSet: 'fiori'}\"\n                  vizType=\"bar\"\n                  height=\"380px\"\n                  width=\"100%\"\n                >\n                  <viz:dataset>\n                    <vizData:FlattenedDataset id=\"hcaDataset\">\n                      <vizData:dimensions>\n                        <vizData:DimensionDefinition name=\"Category\" value=\"{category}\" />\n                      </vizData:dimensions>\n                      <vizData:measures>\n                        <vizData:MeasureDefinition name=\"Count\" value=\"{count}\" />\n                      </vizData:measures>\n                    </vizData:FlattenedDataset>\n                  </viz:dataset>\n                  <viz:feeds>\n                    <feeds:FeedItem uid=\"categoryAxis\" type=\"Dimension\" values=\"Category\" />\n                    <feeds:FeedItem uid=\"valueAxis\"    type=\"Measure\"   values=\"Count\"    />\n                  </viz:feeds>\n                </viz:VizFrame>\n              </l:content>\n              <l:content>\n                <Label id=\"s4hChartLabel\" text=\"\" design=\"Bold\" textAlign=\"Center\" width=\"100%\" class=\"sapUiTinyMarginBottom\" />\n                <viz:VizFrame\n                  id=\"s4hChart\"\n                  uiConfig=\"{applicationSet: 'fiori'}\"\n                  vizType=\"bar\"\n                  height=\"380px\"\n                  width=\"100%\"\n                >\n                  <viz:dataset>\n                    <vizData:FlattenedDataset id=\"s4hDataset\">\n                      <vizData:dimensions>\n                        <vizData:DimensionDefinition name=\"Category\" value=\"{category}\" />\n                      </vizData:dimensions>\n                      <vizData:measures>\n                        <vizData:MeasureDefinition name=\"Count\" value=\"{count}\" />\n                      </vizData:measures>\n                    </vizData:FlattenedDataset>\n                  </viz:dataset>\n                  <viz:feeds>\n                    <feeds:FeedItem uid=\"categoryAxis\" type=\"Dimension\" values=\"Category\" />\n                    <feeds:FeedItem uid=\"valueAxis\"    type=\"Measure\"   values=\"Count\"    />\n                  </viz:feeds>\n                </viz:VizFrame>\n              </l:content>\n            </l:Grid>\n          </content>\n        </Panel>\n\n        <!-- ── Exceptions Panel ──────────────────────────────────────── -->\n        <Panel\n          id=\"exceptionsPanel\"\n          visible=\"false\"\n          headerText=\"Exceptions\"\n          expandable=\"true\"\n          expanded=\"true\"\n          class=\"sapUiSmallMarginBottom\"\n        >\n          <content>\n            <l:Grid defaultSpan=\"XL6 L6 M12 S12\" class=\"sapUiSmallMarginTop sapUiSmallMarginBottom sapUiSmallMarginBeginEnd\">\n              <l:content>\n                <VBox class=\"sapUiSmallMarginBottom\">\n                  <Label text=\"Fit Gap Delta (Manual Check → Fit Gap)\" design=\"Bold\" class=\"sapUiTinyMarginBottom\" />\n                  <Text id=\"exceptionFitGapDelta\" text=\"0\" class=\"atcExceptionValue\" />\n                </VBox>\n              </l:content>\n              <l:content>\n                <VBox class=\"sapUiSmallMarginBottom\">\n                  <Label text=\"Unmaintained Namespaces (Manual Check)\" design=\"Bold\" class=\"sapUiTinyMarginBottom\" />\n                  <Label text=\"Present in SMODILOG but not declared in TRNSPACET\" class=\"sapUiTinyMarginBottom\" />\n                  <List\n                    id=\"unmaintainedNsList\"\n                    noDataText=\"None ✓\"\n                    showNoData=\"true\"\n                    class=\"sapUiTinyMarginTop\"\n                  />\n                </VBox>\n              </l:content>\n            </l:Grid>\n          </content>\n        </Panel>\n\n        <!-- ── Downloads Panel ───────────────────────────────────────── -->\n        <Panel\n          id=\"downloadsPanel\"\n          visible=\"false\"\n          headerText=\"Generated Files\"\n          expandable=\"true\"\n          expanded=\"false\"\n          class=\"sapUiSmallMarginBottom\"\n        >\n          <content>\n            <List id=\"artifactsList\" class=\"sapUiSmallMarginTop\">\n              <items>\n                <CustomListItem id=\"artifactItemTemplate\" visible=\"false\" />\n              </items>\n            </List>\n            <HBox justifyContent=\"Center\" class=\"sapUiSmallMarginTop sapUiSmallMarginBottom\">\n              <Button\n                id=\"downloadAllBtn2\"\n                text=\"Download All Files as ZIP\"\n                icon=\"sap-icon://download\"\n                type=\"Emphasized\"\n                press=\".onDownloadAll\"\n              />\n            </HBox>\n          </content>\n        </Panel>\n\n      </l:VerticalLayout>\n    </content>\n  </Page>\n</mvc:View>\n",
  "com/sap/atcanalysis/view/Upload.view.xml": "<mvc:View\n  controllerName=\"com.sap.atcanalysis.controller.Upload\"\n  xmlns:mvc=\"sap.ui.core.mvc\"\n  xmlns=\"sap.m\"\n  xmlns:l=\"sap.ui.layout\"\n  xmlns:u=\"sap.ui.unified\"\n  xmlns:core=\"sap.ui.core\"\n  displayBlock=\"true\"\n>\n  <Page\n    id=\"uploadPage\"\n    showHeader=\"false\"\n    backgroundDesign=\"Solid\"\n  >\n    <content>\n\n      <!-- ── Top Header Bar ──────────────────────────────────────────── -->\n      <HBox\n        justifyContent=\"SpaceBetween\"\n        alignItems=\"Center\"\n        class=\"atcHeaderBar\"\n      >\n        <HBox alignItems=\"Center\">\n          <Image src=\"./img/sap_logo.svg\" height=\"28px\" alt=\"SAP Logo\" class=\"sapUiTinyMarginEnd\" />\n          <Title text=\"Conversion Assessment Tool\" level=\"H4\" titleStyle=\"H4\" />\n        </HBox>\n        <HBox alignItems=\"Center\">\n          <Label text=\"S/4HANA Code Conversion Assessment\" design=\"Bold\" class=\"sapUiSmallMarginEnd\" />\n        </HBox>\n      </HBox>\n\n      <!-- ── Page Wrapper ──────────────────────────────────────────────── -->\n      <l:VerticalLayout width=\"100%\" class=\"atcPageWrapper sapUiMediumMarginTop\">\n\n        <!-- ── Customer Name ─────────────────────────────────────────── -->\n        <Panel class=\"atcCard sapUiSmallMarginBottom\" expandable=\"false\">\n          <content>\n            <VBox class=\"atcCardContent\">\n              <HBox alignItems=\"Center\" class=\"atcSectionHeader sapUiTinyMarginBottom\">\n                <core:Icon src=\"sap-icon://account\" class=\"atcSectionIcon\" />\n                <Title text=\"Customer\" level=\"H5\" titleStyle=\"H5\" class=\"sapUiTinyMarginBegin\" />\n              </HBox>\n              <Label text=\"Customer Name\" required=\"true\" class=\"atcFieldLabel sapUiTinyMarginBottom\" />\n              <Input\n                id=\"customerInput\"\n                placeholder=\"Enter customer name (e.g. Office Works)\"\n                width=\"420px\"\n                liveChange=\".onCustomerChange\"\n                class=\"atcCustomerInput\"\n              />\n            </VBox>\n          </content>\n        </Panel>\n\n        <!-- ── Analysis Option ───────────────────────────────────────── -->\n        <Panel class=\"atcCard sapUiSmallMarginBottom\" expandable=\"false\">\n          <content>\n            <VBox class=\"atcCardContent\">\n              <HBox alignItems=\"Center\" class=\"atcSectionHeader sapUiTinyMarginBottom\">\n                <core:Icon src=\"sap-icon://settings\" class=\"atcSectionIcon\" />\n                <Title text=\"Analysis Option\" level=\"H5\" titleStyle=\"H5\" class=\"sapUiTinyMarginBegin\" />\n              </HBox>\n              <Label text=\"Select the type of analysis to run\" class=\"atcSectionSubtitle sapUiTinyMarginBottom\" />\n              <SegmentedButton\n                id=\"analysisModeBtn\"\n                selectionChange=\".onModeChange\"\n                width=\"100%\"\n                class=\"atcModeBtn\"\n              >\n                <items>\n                  <SegmentedButtonItem key=\"atc\"           text=\"ATC Only\"          />\n                  <SegmentedButtonItem key=\"atc_clone\"     text=\"ATC + Clone\"       />\n                  <SegmentedButtonItem key=\"atc_tua\"       text=\"ATC + TUA\"         />\n                  <SegmentedButtonItem key=\"atc_tua_clone\" text=\"ATC + TUA + Clone\" />\n                  <SegmentedButtonItem key=\"tua_only\"      text=\"TUA Only\"          />\n                </items>\n              </SegmentedButton>\n            </VBox>\n          </content>\n        </Panel>\n\n        <!-- ── ATC File (visible for all modes except TUA Only) ──────── -->\n        <Panel\n          id=\"atcUploaderPanel\"\n          class=\"atcCard atcFileCard sapUiSmallMarginBottom\"\n          expandable=\"false\"\n        >\n          <content>\n            <VBox class=\"atcCardContent\">\n              <HBox alignItems=\"Center\" class=\"atcSectionHeader sapUiTinyMarginBottom\">\n                <core:Icon src=\"sap-icon://attachment\" class=\"atcSectionIcon\" />\n                <Title text=\"ATC File\" level=\"H5\" titleStyle=\"H5\" class=\"sapUiTinyMarginBegin\" />\n                <ObjectStatus text=\"Required\" state=\"Error\" class=\"sapUiTinyMarginBegin atcRequiredBadge\" />\n              </HBox>\n              <Label text=\"XLSX exported from customer system\" class=\"atcSectionSubtitle sapUiTinyMarginBottom\" />\n              <u:FileUploader\n                id=\"atcFileUploader\"\n                name=\"file\"\n                uploadUrl=\"/atc/upload\"\n                fileType=\"xlsx,xls\"\n                mimeType=\"application/vnd.openxmlformats-officedocument.spreadsheetml.sheet,application/vnd.ms-excel\"\n                multiple=\"false\"\n                uploadOnChange=\"false\"\n                change=\".onAtcFileChange\"\n                uploadComplete=\".onAtcUploadComplete\"\n                placeholder=\"Drop ATC file here or click to browse\"\n                width=\"100%\"\n                class=\"atcUploader\"\n              >\n                <u:parameters>\n                  <u:FileUploaderParameter name=\"role\" value=\"atc\" />\n                </u:parameters>\n              </u:FileUploader>\n              <ObjectStatus\n                id=\"atcFileStatus\"\n                text=\"No file selected\"\n                state=\"None\"\n                class=\"sapUiTinyMarginTop\"\n              />\n            </VBox>\n          </content>\n        </Panel>\n\n        <!-- ── Clone File (ATC + Clone, ATC + TUA + Clone) ───────────── -->\n        <Panel\n          id=\"cloneUploaderPanel\"\n          class=\"atcCard atcFileCard sapUiSmallMarginBottom\"\n          expandable=\"false\"\n          visible=\"false\"\n        >\n          <content>\n            <VBox class=\"atcCardContent\">\n              <HBox alignItems=\"Center\" class=\"atcSectionHeader sapUiTinyMarginBottom\">\n                <core:Icon src=\"sap-icon://copy\" class=\"atcSectionIcon\" />\n                <Title text=\"Clone List\" level=\"H5\" titleStyle=\"H5\" class=\"sapUiTinyMarginBegin\" />\n                <ObjectStatus text=\"Required\" state=\"Error\" class=\"sapUiTinyMarginBegin atcRequiredBadge\" />\n              </HBox>\n              <Label text=\"Clone analysis XLSX (filename starts with 'clone')\" class=\"atcSectionSubtitle sapUiTinyMarginBottom\" />\n              <u:FileUploader\n                id=\"cloneFileUploader\"\n                name=\"file\"\n                uploadUrl=\"/atc/upload\"\n                fileType=\"xlsx,xls\"\n                multiple=\"false\"\n                uploadOnChange=\"false\"\n                change=\".onOptionalFileChange\"\n                uploadComplete=\".onCloneUploadComplete\"\n                placeholder=\"Drop clone file here or click to browse\"\n                width=\"100%\"\n                class=\"atcUploader\"\n              >\n                <u:parameters>\n                  <u:FileUploaderParameter name=\"role\" value=\"clone\" />\n                </u:parameters>\n              </u:FileUploader>\n              <ObjectStatus\n                id=\"cloneFileStatus\"\n                text=\"No file selected\"\n                state=\"None\"\n                class=\"sapUiTinyMarginTop\"\n              />\n            </VBox>\n          </content>\n        </Panel>\n\n        <!-- ── TUA Files (ATC + TUA, ATC + TUA + Clone, TUA Only) ──────── -->\n        <Panel\n          id=\"tuaUploaderPanel\"\n          class=\"atcCard atcFileCard sapUiSmallMarginBottom\"\n          expandable=\"false\"\n          visible=\"false\"\n        >\n          <content>\n            <VBox class=\"atcCardContent\">\n              <HBox alignItems=\"Center\" class=\"atcSectionHeader sapUiSmallMarginBottom\">\n                <core:Icon src=\"sap-icon://database\" class=\"atcSectionIcon\" />\n                <Title text=\"TUA Files\" level=\"H5\" titleStyle=\"H5\" class=\"sapUiTinyMarginBegin\" />\n                <ObjectStatus text=\"SMODILOG + TRNSPACET required\" state=\"Error\" class=\"sapUiTinyMarginBegin atcRequiredBadge\" />\n              </HBox>\n              <l:Grid defaultSpan=\"XL4 L4 M12 S12\" class=\"sapUiSmallMarginTop\">\n                <!-- SMODILOG -->\n                <l:content>\n                  <VBox class=\"atcTuaFileGroup\">\n                    <Label text=\"SMODILOG File\" required=\"true\" class=\"atcFieldLabel sapUiTinyMarginBottom\" />\n                    <Label text=\"SMODILOG export from SAP\" class=\"atcSectionSubtitle sapUiTinyMarginBottom\" />\n                    <u:FileUploader\n                      id=\"smodilogUploader\"\n                      name=\"file\"\n                      uploadUrl=\"/atc/upload\"\n                      fileType=\"xlsx,xls\"\n                      multiple=\"false\"\n                      uploadOnChange=\"false\"\n                      change=\".onOptionalFileChange\"\n                      uploadComplete=\".onSmodilogUploadComplete\"\n                      placeholder=\"Drop SMODILOG file here or click to browse\"\n                      width=\"100%\"\n                      class=\"atcUploader\"\n                    >\n                      <u:parameters>\n                        <u:FileUploaderParameter name=\"role\" value=\"smodilog\" />\n                      </u:parameters>\n                    </u:FileUploader>\n                    <ObjectStatus id=\"smodilogStatus\" text=\"No file selected\" state=\"None\" class=\"sapUiTinyMarginTop\" />\n                  </VBox>\n                </l:content>\n                <!-- TRNSPACET -->\n                <l:content>\n                  <VBox class=\"atcTuaFileGroup\">\n                    <Label text=\"TRNSPACET File\" required=\"true\" class=\"atcFieldLabel sapUiTinyMarginBottom\" />\n                    <Label text=\"TRNSPACET export from SAP\" class=\"atcSectionSubtitle sapUiTinyMarginBottom\" />\n                    <u:FileUploader\n                      id=\"trnspacetUploader\"\n                      name=\"file\"\n                      uploadUrl=\"/atc/upload\"\n                      fileType=\"xlsx,xls\"\n                      multiple=\"false\"\n                      uploadOnChange=\"false\"\n                      change=\".onOptionalFileChange\"\n                      uploadComplete=\".onTrnspacetUploadComplete\"\n                      placeholder=\"Drop TRNSPACET file here or click to browse\"\n                      width=\"100%\"\n                      class=\"atcUploader\"\n                    >\n                      <u:parameters>\n                        <u:FileUploaderParameter name=\"role\" value=\"trnspacet\" />\n                      </u:parameters>\n                    </u:FileUploader>\n                    <ObjectStatus id=\"trnspacetStatus\" text=\"No file selected\" state=\"None\" class=\"sapUiTinyMarginTop\" />\n                  </VBox>\n                </l:content>\n              </l:Grid>\n            </VBox>\n          </content>\n        </Panel>\n\n        <!-- ── Migration Type ─────────────────────────────────────────── -->\n        <Panel class=\"atcCard sapUiSmallMarginBottom\" expandable=\"false\">\n          <content>\n            <VBox class=\"atcCardContent\">\n              <!-- Migration Type -->\n              <VBox class=\"atcOptionGroup\">\n                  <HBox alignItems=\"Center\" class=\"atcSectionHeader sapUiTinyMarginBottom\">\n                    <core:Icon src=\"sap-icon://journey-change\" class=\"atcSectionIcon\" />\n                    <Title text=\"Migration Type\" level=\"H5\" titleStyle=\"H5\" class=\"sapUiTinyMarginBegin\" />\n                  </HBox>\n                  <Label text=\"System conversion or in-place upgrade\" class=\"atcSectionSubtitle sapUiTinyMarginBottom\" />\n                  <SegmentedButton\n                    id=\"migrationTypeBtn\"\n                    width=\"400px\"\n                    selectionChange=\".onMigrationTypeChange\"\n                    selectedItem=\"migConversionItem\"\n                  >\n                    <items>\n                      <SegmentedButtonItem id=\"migConversionItem\" text=\"Conversion (ECC → S/4HANA)\" key=\"conversion\" />\n                      <SegmentedButtonItem id=\"migUpgradeItem\"    text=\"Upgrade (S/4HANA → S/4HANA)\" key=\"upgrade\"   />\n                    </items>\n                  </SegmentedButton>\n              </VBox>\n            </VBox>\n          </content>\n        </Panel>\n\n        <!-- ── Run Button ────────────────────────────────────────────── -->\n        <VBox alignItems=\"Center\" class=\"sapUiMediumMarginBottom sapUiSmallMarginTop\">\n          <Button\n            id=\"runBtn\"\n            text=\"Run Analysis\"\n            type=\"Emphasized\"\n            icon=\"sap-icon://play\"\n            press=\".onRunAnalysis\"\n            enabled=\"false\"\n            class=\"atcRunBtn\"\n          />\n        </VBox>\n\n        <!-- ── Status / Progress ────────────────────────────────────── -->\n        <VBox id=\"statusBox\" visible=\"false\" alignItems=\"Center\" class=\"sapUiSmallMarginBottom atcStatusBox\">\n          <BusyIndicator id=\"progressIndicator\" size=\"2rem\" class=\"sapUiSmallMarginBottom\" />\n          <Text id=\"statusText\" text=\"\" textAlign=\"Center\" class=\"atcStatusText\" />\n        </VBox>\n\n        <!-- ── Error Strip ───────────────────────────────────────────── -->\n        <MessageStrip\n          id=\"errorStrip\"\n          type=\"Error\"\n          showIcon=\"true\"\n          showCloseButton=\"true\"\n          visible=\"false\"\n          class=\"sapUiSmallMarginBottom\"\n          close=\".onCloseError\"\n        />\n\n      </l:VerticalLayout>\n    </content>\n  </Page>\n</mvc:View>\n"
}, "com.sap.atcanalysis.Component-preload");
